"""Union-find orbit enumeration and reconstruction of invariant patterns."""

from __future__ import annotations

from typing import Callable, Dict, List, Sequence, Tuple

Cell = Tuple[int, int]
Action = Callable[[Cell], Cell]


def enumerate_orbits(
    cells: Sequence[Cell], generators: Sequence[Action]
) -> List[List[Cell]]:
    """Orbit partition of `cells` under the group generated by `generators`.

    Unlike the Burnside route, this needs only a *generating set*, and it
    returns the orbits themselves rather than merely their number.

    Complexity: Theta(|cells| * |generators|) union operations, each amortized
    inverse-Ackermann, so effectively linear in the size of the incidence data.
    """
    index: Dict[Cell, int] = {c: i for i, c in enumerate(cells)}
    parent: List[int] = list(range(len(cells)))

    def find(x: int) -> int:
        root = x
        while parent[root] != root:
            root = parent[root]
        while parent[x] != root:          # path compression
            parent[x], x = root, parent[x]
        return root

    def union(x: int, y: int) -> None:
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[max(rx, ry)] = min(rx, ry)

    for g in generators:
        for c in cells:
            union(index[c], index[g(c)])

    buckets: Dict[int, List[Cell]] = {}
    for c in cells:
        buckets.setdefault(find(index[c]), []).append(c)
    return [buckets[k] for k in sorted(buckets)]


def pattern_from_orbit_bits(
    orbs: Sequence[Sequence[Cell]], bits: Sequence[int]
) -> Dict[Cell, int]:
    """Build the invariant pattern that switches on exactly the chosen orbits.

    This realizes the bijection {invariant patterns} <-> {0,1}^{orbits} that
    underlies the orbit capacity theorem: every one of the 2^m invariant
    patterns arises from exactly one bit-vector of length m.
    """
    if len(orbs) != len(bits):
        raise ValueError("one bit is required per orbit")
    out: Dict[Cell, int] = {}
    for orb, b in zip(orbs, bits):
        for c in orb:
            out[c] = int(b)
    return out


if __name__ == "__main__":
    p, q = 6, 2
    cells = [(t, n) for t in range(p) for n in range(q)]
    # generator: the glide (t, n) -> (t + 3, -n)
    gen = [lambda c: ((c[0] + p // 2) % p, (-c[1]) % q)]
    orbs = enumerate_orbits(cells, gen)
    print(f"{len(orbs)} orbits on the {p}x{q} torus under the glide:")
    for i, o in enumerate(orbs):
        print(f"  orbit {i}: {sorted(o)}")
    pat = pattern_from_orbit_bits(orbs, [1, 0, 1, 0, 1, 0])
    print("one invariant pattern:", sorted(c for c, v in pat.items() if v))
    assert len(orbs) == p * q // 2

"""Canon synthesis at a prescribed onset count, and the decision procedure."""

from __future__ import annotations

from math import gcd
from typing import List, Optional, Set, Tuple

Cell = Tuple[int, int]


def shift_order(p: int, g: int) -> int:
    """The additive order d of g in Z_p (with ord(0) = 1)."""
    if p <= 0:
        raise ValueError("p must be positive")
    return p // gcd(p, g % p) if g % p else 1


def onset_count_is_achievable(p: int, q: int, g: int, k: int) -> bool:
    """Decision procedure: is k the onset count of some canon at distance g?

    The complete criterion is  d | k  and  k <= p q,  where d = ord(g).  Both
    directions are theorems: divisibility is forced because the shift group
    generated by g acts freely, and every admissible k is attained by a union
    of whole orbits.
    """
    return k >= 0 and k <= p * q and k % shift_order(p, g) == 0


def synthesize_canon(p: int, q: int, g: int, k: int) -> Optional[Set[Cell]]:
    """Return the onset set of a canon at distance g with exactly k onsets.

    Returns None exactly when no such canon exists.  The construction takes the
    union of j = k/d complete orbits of the shift group generated by g, each of
    which has exactly d = ord(g) cells because the action is free.

    Complexity: Theta(p q).
    """
    if not onset_count_is_achievable(p, q, g, k):
        return None
    d = shift_order(p, g)
    j = k // d
    seen: Set[Cell] = set()
    chosen: Set[Cell] = set()
    taken = 0
    for n in range(q):
        for t in range(p):
            if (t, n) in seen:
                continue
            orbit = {((t + i * g) % p, n) for i in range(d)}
            seen |= orbit
            if taken < j:
                chosen |= orbit
                taken += 1
    return chosen


def is_canon_at(p: int, q: int, onsets: Set[Cell], g: int) -> bool:
    """Verify directly that shifting by g in time reproduces the pattern."""
    return all((((t + g) % p, n) in onsets) == ((t, n) in onsets)
               for t in range(p) for n in range(q))


def onset_spectrum(p: int, q: int, g: int) -> List[int]:
    """The complete set of achievable onset counts, in increasing order."""
    d = shift_order(p, g)
    return list(range(0, p * q + 1, d))


if __name__ == "__main__":
    p, q, g = 12, 3, 4
    print(f"torus {p}x{q}, canon at time distance g = {g}")
    print(f"  ord(g)   = {shift_order(p, g)}")
    print(f"  spectrum = {onset_spectrum(p, q, g)}")
    for k in (0, 9, 10, 36):
        s = synthesize_canon(p, q, g, k)
        if s is None:
            print(f"  k = {k:>2}: impossible")
        else:
            assert is_canon_at(p, q, s, g) and len(s) == k
            print(f"  k = {k:>2}: canon built and verified")
